parameters.jsCode:
return [{ json: {
  gym_name: 'Your Gym', branch: 'Main Branch', tz: 'Asia/Kolkata',
  owner_whatsapp: 'REPLACE_WITH_OWNER_NUMBER', front_desk_whatsapp: 'REPLACE_WITH_FRONT_DESK_NUMBER',
  renewal_link: 'https://example.com/renew',
  cooldown_days: 14, renewal_window_days: 7, lapsed_window_days: 15, max_outreach_per_day: 40, min_tenure_days_for_drop: 21,
  tiers: { critical: 70, high: 50, medium: 35 },
  offers: {
    lapsed:          { title: 'Come-back offer',     detail: '25% off a 3-month plan + a free PT session', discount_pct: 25, valid_days: 7 },
    renewal_at_risk: { title: 'Renew & reset',       detail: '15% off renewal + 2 free PT sessions to restart your plan', discount_pct: 15, valid_days: 7 },
    winback_critical:{ title: 'We miss you',         detail: '1 free PT session + 20% off your next renewal', discount_pct: 20, valid_days: 7 },
    winback_high:    { title: 'Flex freeze or boost', detail: 'Freeze up to 15 days free, or bring a friend for free this week', discount_pct: 0, valid_days: 10 },
    reengage:        { title: 'New class invite',    detail: 'A free guest pass for a group class of your choice', discount_pct: 0, valid_days: 10 },
    renewal:         { title: 'Early-bird renewal',  detail: '10% off if you renew before expiry', discount_pct: 10, valid_days: 7 }
  }
} }];

const cfg = $('GymOS Config1').first().json;
const today = $now.setZone(cfg.tz).startOf('day');
const parse = s => { s = String(s || '').trim(); if (!s) return null;
  let d = DateTime.fromISO(s.replace(' ', 'T'), { zone: cfg.tz });
  if (!d.isValid) { const m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})(?:[ T](\d{1,2}):(\d{2}))?/);
    if (m) d = DateTime.fromObject({ day: +m[1], month: +m[2], year: +m[3], hour: +(m[4] || 0), minute: +(m[5] || 0) }, { zone: cfg.tz }); }
  return d.isValid ? d : null; };
const members = $('Read Members1').all().map(i => i.json)
  .filter(m => m.member_id && !/cancel|inactive|deleted/i.test(m.status || ''));
const visits = {};
for (const { json: c } of $('Read Check-ins1').all()) {
  const d = parse(c.checkin_at); if (!c.member_id || !d) continue;
  (visits[c.member_id] = visits[c.member_id] || new Set()).add(d.toFormat('yyyy-LL-dd'));
}
const offers = $('Read Offer Log1').all().map(i => i.json).filter(o => o.member_id);
const lastOffer = {};
offers.forEach(o => { if (!lastOffer[o.member_id] || String(o.sent_at) > String(lastOffer[o.member_id].sent_at)) lastOffer[o.member_id] = o; });
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 36).toString(36)).join('').toUpperCase();

const scored = members.map(m => {
  const days = [...(visits[m.member_id] || [])].map(s => DateTime.fromISO(s, { zone: cfg.tz })).sort((a, b) => b - a);
  const ago = d => Math.floor(today.diff(d.startOf('day'), 'days').days);
  const join = parse(m.join_date) || today, exp = parse(m.expiry_date);
  const tenure = Math.max(0, Math.floor(today.diff(join, 'days').days));
  const last = days[0];
  const since = last ? ago(last) : tenure;
  const n7 = days.filter(d => ago(d) < 7).length, n14 = days.filter(d => ago(d) < 14).length;
  const base = days.filter(d => ago(d) >= 14 && ago(d) < 56).length / 6;         // visits/week, weeks 3–8
  const recentWk = n14 / 2;
  const drop = tenure >= cfg.min_tenure_days_for_drop ? (base > 0 ? Math.max(0, 1 - recentWk / base) : (n14 === 0 ? 1 : 0)) : 0;
  const toExp = exp ? Math.floor(exp.diff(today, 'days').days) : 999;
  const monthly = /month|1m|30/i.test(m.plan || '');
  let s = Math.min(35, since * 2.5) + drop * 30
    + (toExp < 0 ? 20 : toExp <= 7 ? 16 : toExp <= 14 ? 10 : toExp <= 30 ? 5 : 0)
    + (tenure < 90 ? 10 : tenure < 180 ? 5 : 0) + (monthly ? 5 : 0);
  if (n7 >= 3) s *= 0.4;
  const score = Math.round(Math.min(100, s));
  const reasons = [];
  if (since >= 7) reasons.push(`no check-in for ${since} days`);
  if (drop >= 0.4 && base > 0) reasons.push(`attendance down ${Math.round(drop * 100)}% (${recentWk.toFixed(1)}/wk vs ${base.toFixed(1)}/wk)`);
  if (toExp >= 0 && toExp <= 14) reasons.push(`membership expires in ${toExp} days`);
  if (toExp < 0) reasons.push(`membership expired ${-toExp} days ago`);
  if (tenure < 90) reasons.push(`new member (${tenure} days)`);
  const tier = score >= cfg.tiers.critical ? 'Critical' : score >= cfg.tiers.high ? 'High' : score >= cfg.tiers.medium ? 'Medium' : 'Low';
  const lapsed = toExp < 0 && -toExp <= cfg.lapsed_window_days;
  const renewalDue = toExp >= 0 && toExp <= cfg.renewal_window_days;
  const segment = lapsed ? 'lapsed' : renewalDue ? (score >= cfg.tiers.high ? 'renewal_at_risk' : 'renewal')
    : tier === 'Critical' ? 'winback_critical' : tier === 'High' ? 'winback_high' : tier === 'Medium' ? 'reengage' : null;
  const lo = lastOffer[m.member_id];
  const cooling = lo && Math.floor(today.diff(parse(lo.sent_at) || today.minus({ years: 1 }), 'days').days) < cfg.cooldown_days;
  const optedOut = /yes|true|1/i.test(String(m.opted_out || ''));
  return { ...m, phone: String(m.phone || '').replace(/\D/g, ''), score, tier, segment, reasons, since_last_visit: since,
    visits_7d: n7, visits_14d: n14, baseline_per_week: Math.round(base * 10) / 10, drop_pct: Math.round(drop * 100),
    days_to_expiry: toExp === 999 ? '' : toExp, tenure_days: tenure, last_visit: last ? last.toFormat('dd LLL') : 'never',
    plan_price: Number(m.plan_price) || 0, eligible: !!segment && !cooling && !optedOut && !!m.phone,
    skip_reason: !segment ? '' : optedOut ? 'opted_out' : cooling ? 'cooldown' : !m.phone ? 'no_phone' : '' };
});

const targets = scored.filter(m => m.eligible)
  .sort((a, b) => b.score * (b.plan_price || 1) - a.score * (a.plan_price || 1)).slice(0, cfg.max_outreach_per_day)
  .map(m => { const o = cfg.offers[m.segment];
    return { json: { type: 'outreach', ...m, offer_title: o.title, offer_detail: o.detail, discount_pct: o.discount_pct,
      offer_code: `${m.segment === 'renewal' ? 'RN' : 'WB'}-${String(m.member_id).slice(-4)}-${hex(4)}`,
      offer_expiry: today.plus({ days: o.valid_days }).toFormat('dd LLL yyyy'),
      task_priority: m.tier === 'Critical' || m.segment === 'lapsed' ? 1 : m.tier === 'High' || m.segment === 'renewal_at_risk' ? 2 : 3 } }; });

const byTier = t => scored.filter(m => m.tier === t).length;
const atRisk = scored.filter(m => ['Critical', 'High'].includes(m.tier));
const byTrainer = {};
targets.forEach(({ json: t }) => { const k = t.trainer_name || 'Unassigned';
  (byTrainer[k] = byTrainer[k] || { trainer_name: k, trainer_phone: String(t.trainer_phone || '').replace(/\D/g, ''), members: [] })
    .members.push(`${t.name} (${t.tier} ${t.score}, ${t.reasons[0] || t.segment})`); });
const summary = { type: 'summary', date: today.toFormat('yyyy-LL-dd'), active_members: scored.length,
  critical: byTier('Critical'), high: byTier('High'), medium: byTier('Medium'), low: byTier('Low'),
  revenue_at_risk: atRisk.reduce((a, m) => a + m.plan_price, 0),
  renewals_due_7d: scored.filter(m => m.days_to_expiry !== '' && m.days_to_expiry >= 0 && m.days_to_expiry <= 7).length,
  lapsed_15d: scored.filter(m => m.segment === 'lapsed').length, outreach_today: targets.length,
  skipped_cooldown: scored.filter(m => m.skip_reason === 'cooldown').length,
  skipped_opt_out: scored.filter(m => m.skip_reason === 'opted_out').length,
  avg_score: scored.length ? Math.round(scored.reduce((a, m) => a + m.score, 0) / scored.length) : 0,
  top_risks: atRisk.sort((a, b) => b.score - a.score).slice(0, 5).map(m => `${m.name} ${m.score} (${m.reasons[0] || ''})`),
  by_trainer: Object.values(byTrainer) };
return [...targets, { json: summary }];

const m = $('Route: Outreach or Summary1').item.json;
const ai = $json.message?.content || {};
const cfg = $('GymOS Config1').first().json;
const msg = ai.message || `Hi ${String(m.name).split(' ')[0]}! We miss you at ${cfg.gym_name} 💪 ${m.offer_detail}. Code ${m.offer_code}, valid till ${m.offer_expiry}. Reply YES to claim.`;
return { json: { ...m, wa_message: msg + (m.segment.startsWith('renewal') || m.segment === 'lapsed' ? `

Renew: ${cfg.renewal_link}?code=${m.offer_code}` : ''),
  trainer_note: ai.trainer_note || `Check in on ${m.name}'s ${m.goal || 'goals'}; offer ${m.offer_title}.`,
  task_name: `Call ${m.name} – ${m.tier} churn risk (${m.score}) · ${m.offer_title}`,
  task_body: `Member: ${m.name} (${m.member_id}) · ${m.phone}
Plan: ${m.plan} · expires ${m.expiry_date || '–'} (${m.days_to_expiry} days)
Last visit: ${m.last_visit} · ${m.visits_14d} visits/14d vs ${m.baseline_per_week}/wk usual
Why: ${m.reasons.join('; ')}
Offer sent: ${m.offer_title}: ${m.offer_detail} (code ${m.offer_code}, till ${m.offer_expiry})

Talking points: ${ai.trainer_note || '-'}
Trainer: ${m.trainer_name || 'Unassigned'}` } };

const s = $json, cfg = $('GymOS Config1').first().json;
const out = s.by_trainer.filter(t => t.trainer_phone).map(t => ({ json: { kind: 'trainer', to: t.trainer_phone,
  text: `🏋️ Hi ${t.trainer_name}, today's retention calls (${t.members.length}):
` + t.members.map((m, i) => `${i + 1}. ${m}`).join('
') +
    `

The offers have already gone out on WhatsApp. Tasks are in ClickUp. A quick personal call doubles the comeback rate 💪` } }));
out.push({ json: { kind: 'owner', to: cfg.owner_whatsapp, text:
  `📊 *${cfg.gym_name} – Retention ${s.date}*
Active members: ${s.active_members} · avg risk ${s.avg_score}
` +
  `🔴 Critical ${s.critical} · 🟠 High ${s.high} · 🟡 Medium ${s.medium}
💰 Revenue at risk: ₹${s.revenue_at_risk.toLocaleString('en-IN')}
` +
  `🔁 Renewals due ≤7d: ${s.renewals_due_7d} · Lapsed ≤15d: ${s.lapsed_15d}
📨 Offers sent today: ${s.outreach_today} (cooldown ${s.skipped_cooldown}, opted-out ${s.skipped_opt_out})
` +
  (s.top_risks.length ? `
Top risks:
${s.top_risks.map(r => '• ' + r).join('
')}` : '') } });
return out;

const out = [];
for (const { json: j } of $input.all()) {
  const v = j.value || j.entry?.[0]?.changes?.[0]?.value || j;
  for (const m of v.messages || []) {
    const text = m.text?.body || m.button?.text || m.interactive?.button_reply?.title || m.interactive?.list_reply?.title || '';
    if (!text) continue;
    out.push({ json: { phone: String(m.from).replace(/\D/g, ''), text: text.slice(0, 1000), wa_name: (v.contacts || [])[0]?.profile?.name || '' } });
  }
}
return out.slice(0, 1);

const r = $('Parse Reply1').first().json;
const m = $('Find Member1').first()?.json || {};
const offers = $input.all().map(i => i.json).filter(o => o.offer_code).sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at)));
const o = offers[0] || {};
return [{ json: { ...r, known_member: !!m.member_id, member_id: m.member_id || '', name: m.name || r.wa_name || 'there',
  language: m.language || 'English', trainer_name: m.trainer_name || '', trainer_phone: String(m.trainer_phone || '').replace(/\D/g, ''),
  plan: m.plan || '', expiry_date: m.expiry_date || '', offer_code: o.offer_code || '', offer_title: o.offer_title || '',
  offer_status: o.status || '', offer_expiry: o.offer_expiry || '', segment: o.segment || '' } }];

